use vlajmaji::lexicon::*;
use vlajmaji::search::{DictionarySearchEngine,DictionaryExactOptions,ReferenceStatus};
use sha2::{Digest,Sha256};
fn sha(x:&[u8])->String{format!("{:x}",Sha256::digest(x))}
fn options(raw:&[u8])->LaLojbanImportOptions{LaLojbanImportOptions{revision:"0".repeat(40),expected_raw_sha256:sha(raw),raw_locator:Some("https://example.invalid/synthetic-la".into()),notice_locator:Some("https://example.invalid/synthetic-software-notice".into())}}
fn la(raw:&[u8])->LaLojbanImport{import_la_lojban_export(raw,&options(raw)).unwrap()}
const ROW:&str=r#"{"word":"farvi","word_type":"gismu","definition":"synthetic develops","definition_id":333,"score":1.2500,"selmaho":null,"notes":"note","jargon":"domain","gloss_keywords":[{"word":"growth","sense":"native"}],"place_keywords":[{"place":1}],"rafsi":"fav farv","etymology":"source statement","user":{"username":"shared","realname":"A Person"}}"#;
fn raw()->Vec<u8>{format!("[{ROW}]").into_bytes()}
fn jbotci(raw:&[u8])->Dictionary{let meta=format!("language_tag = \"en\"\nlanguage_realname = \"English\"\nsource_language_tag = \"jbo\"\nformat = \"json\"\npositive_scores_only = false\nfilename = \"dictionary-en.json\"\nmetadata_url = \"https://example.invalid/languages\"\ndownload_url = \"https://example.invalid/synthetic\"\nlensisku_created_at = \"2026-10-04T03:07:08Z\"\nsha256 = \"{}\"\ndefinition_count = 1\nentry_count = 1\n",sha(raw));import_jbotci_export(raw,meta.as_bytes(),&JbotciImportOptions{revision:"0".repeat(40),expected_raw_sha256:sha(raw),expected_metadata_sha256:sha(meta.as_bytes())}).unwrap().into_dictionary()}
fn main(){
 let r=raw();let x=la(&r);let m=x.dictionary().metadata();assert_eq!((m.entries.len(),m.assertions.len(),m.contexts.len(),m.forms.len(),m.etymologies.len(),m.extensions.len()),(1,1,3,2,1,3));assert_eq!(m.entries[0].selmaho,Presence::Null);assert_eq!(m.assertions[0].source_score,Presence::Value(RawJson::new("1.2500").unwrap()));assert_eq!(x.dictionary().registry().as_document().contributors.len(),1);
 let mut o=options(&r);o.revision="1".repeat(40);let y=import_la_lojban_export(&r,&o).unwrap();assert_ne!(m.releases[0].id,y.dictionary().metadata().releases[0].id);assert_eq!(m.assertions[0].occurrence,y.dictionary().metadata().assertions[0].occurrence);assert_eq!(m.assertions[0].id,y.dictionary().metadata().assertions[0].id);
 assert!(matches!(compose_dictionaries(vec![x.clone().into_dictionary(),y.into_dictionary()]),Err(PackError::Conflict{..})));
 let mut derived=LaLojbanImportOptions::default();derived.expected_raw_sha256=sha(&r);derived.revision="2".repeat(40);let routed=import_la_lojban_export(&r,&derived).unwrap();let cap=&routed.dictionary().captures()[0];assert!(cap.metadata.locator.contains(&format!("/{}/assets/dumps/en.json",derived.revision)));assert_eq!(cap.metadata.notice_locator,Presence::Value(format!("https://github.com/La-Lojban/lojban/blob/{}/README.md",derived.revision)));assert_eq!(x.dictionary().captures()[0].metadata.locator,"https://example.invalid/synthetic-la");
 let escaped=la(br#"[{"word":"farvi","word_type":"gismu","definition":"d","a/b~":{"x/y~":1,"x/y~":2}}]"#);let diag=escaped.dictionary().metadata().releases[0].diagnostics.iter().find(|d|d.code=="duplicate_key_path").unwrap();assert!(diag.message.contains("/0/a~1b~0/x~1y~0"),"{}",diag.message);assert_eq!(diag.occurrence.as_ref().unwrap().locator,"/0");assert_eq!(escaped.report().excluded_occurrences,1);assert_eq!(escaped.dictionary().captures()[0].occurrences[0].fields.last().unwrap().raw_value,r#"{"x/y~":1,"x/y~":2}"#);
 let doubled=la(format!("[{ROW},{ROW}]").as_bytes());assert_eq!(doubled.report().input_rows,2);assert_eq!(doubled.dictionary().metadata().assertions.len(),2);assert_ne!(doubled.dictionary().metadata().assertions[0].occurrence,doubled.dictionary().metadata().assertions[1].occurrence);
 for id in ["2","1e9999"]{let data=format!("[{{\"word\":\"farvi\",\"word_type\":\"gismu\",\"definition\":\"native id\",\"definition_id\":{id}}}]");let t=la(data.as_bytes());assert_eq!(t.dictionary().registry().as_document().occurrences[0].native_assertion_id.as_deref(),Some(id));}
 for data in [br#"[{"word":"farvi","word":"other","word_type":"gismu","definition":"d"}]"#.as_slice(),br#"[{"word":"farvi","word_type":"gismu","definition":"d","user":{"username":"a","username":"b"}}]"#.as_slice(),br#"[42]"#.as_slice()]{let t=la(data);assert_eq!(t.report().input_rows,1);assert_eq!(t.report().excluded_occurrences,1);assert_eq!(t.dictionary().captures().len(),1);assert!(t.dictionary().metadata().releases[0].diagnostics.len()>0);}
 for (field,value,code) in [("selmaho","{}","invalid_selmaho"),("definition_id","[]","invalid_definition_id"),("notes","{}","invalid_notes"),("jargon","[]","invalid_jargon"),("gloss_keywords","3","invalid_gloss_keywords"),("place_keywords","{}","invalid_place_keywords"),("rafsi","[3]","invalid_reported_form"),("etymology","{}","invalid_etymology"),("user","{}","invalid_user")] {
 let data=format!("[{{\"word\":\"farvi\",\"word_type\":\"gismu\",\"definition\":\"d\",\"{field}\":{value}}}]");let t=la(data.as_bytes());assert_eq!(t.report().lexical_occurrences,1,"{field}");assert_eq!(t.report().excluded_occurrences,0,"{field}");assert_eq!(t.report().diagnostics.get(code),Some(&1),"{field}");assert_eq!(t.dictionary().captures()[0].occurrences[0].fields.last().unwrap().raw_value,value,"{field}");
 }
 let unknown=la(br#"[{"word":"farvi","word_type":"gismu","definition":"d","unknown":{"nested":[1,2]}}]"#);assert_eq!(unknown.report().lexical_occurrences,1);assert_eq!(unknown.report().diagnostics.get("unknown_native_field"),Some(&1));assert_eq!(unknown.dictionary().metadata().extensions.len(),1);
 for data in [b"{".as_slice(),b"{}".as_slice()]{assert!(matches!(import_la_lojban_export(data,&options(data)),Err(LaLojbanImportError::InvalidJson(_))));}
 let bad=b"\xff";assert!(matches!(import_la_lojban_export(bad,&options(bad)),Err(LaLojbanImportError::InvalidUtf8)));
 let mut bad=options(&r);bad.expected_raw_sha256="0".repeat(64);assert!(matches!(import_la_lojban_export(&r,&bad),Err(LaLojbanImportError::HashMismatch{..})));bad=options(&r);bad.revision="not-a-revision".into();assert!(matches!(import_la_lojban_export(&r,&bad),Err(LaLojbanImportError::InvalidOptions(_))));
 for kind in ["source","contributor"]{let mut doc=la(&r).into_dictionary().into_document();let mut reg=doc.registry.into_document();if kind=="source"{reg.sources[0].display_name="different source body".into();}else{reg.contributors[0].display_name="different contributor body".into();}doc.registry=SourceRegistry::from_document(reg).unwrap();let changed=Dictionary::from_document(doc).unwrap();assert!(matches!(compose_dictionaries(vec![la(&r).into_dictionary(),changed]),Err(PackError::Conflict{..})));}
 let mut g=vec![b' ';158];g[1..6].copy_from_slice(b"farvi");g[62..63].copy_from_slice(b"d");let n=b"Explicit synthetic notice";let mut d=import_llg_lists(&g,b"",b"",n,&LlgImportOptions{expected_gismu_sha256:sha(&g),expected_cmavo_sha256:sha(b""),expected_rafsi_sha256:sha(b""),expected_notice_sha256:sha(n),base_locator:"https://example.invalid/alias-negative".into()}).unwrap().into_dictionary().into_document();let mut reg=d.registry.into_document();reg.aliases.push(SourceAlias{source:SourceId::new("llg").unwrap(),text:"LSK".into(),status:AliasStatus::Active,evidence:None});d.registry=SourceRegistry::from_document(reg).unwrap();let alias_model=Dictionary::from_document(d).unwrap();assert!(matches!(compose_dictionaries(vec![la(&r).into_dictionary(),alias_model]),Err(PackError::Registry(_))));
 let with_excluded=la(format!("[{ROW},42]").as_bytes()).into_dictionary();let excluded=with_excluded.metadata().assertions[1].occurrence.clone();let rel=with_excluded.metadata().releases[0].id.clone();
 let combined=compose_dictionaries(vec![with_excluded,jbotci(&r)]).unwrap();assert_eq!((combined.registry().as_document().sources.len(),combined.registry().as_document().contributors.len(),combined.metadata().assertions.len()),(1,1,3));
 let path=std::path::Path::new("/tmp/vlajmaji-p01-a03-cdc/s03/tiny-composed-store01");let bytes=combined.to_json_bytes().unwrap();let engine=DictionarySearchEngine::build(path,&bytes).unwrap();drop(engine);let s=vlajmaji::store::DictionaryStore::open(path).unwrap();assert_eq!(s.dictionary().unwrap(),combined);drop(s);let engine=DictionarySearchEngine::open(path).unwrap();let all=engine.exact("farvi",DictionaryExactOptions::default()).unwrap();assert_eq!((all.totals.occurrences,all.totals.distinct_spellings,all.totals.source_groups),(2,1,1));for source in ["LSK","lensisku"]{let q=engine.exact("farvi",DictionaryExactOptions{sources:vec![source.into()],..Default::default()}).unwrap();assert_eq!(q.groups,all.groups);assert_eq!(q.totals,all.totals);}
 assert!(engine.exact("farvi",DictionaryExactOptions{sources:vec!["La-Lojban".into()],..Default::default()}).is_err());
 let expected:Vec<_>=all.groups.iter().flat_map(|g|g.hits.iter().map(|h|h.assertion.id.clone())).collect();let mut got=Vec::new();let mut cursor=None;for _ in 0..2{let page=engine.exact("farvi",DictionaryExactOptions{page_size:Some(1),cursor,..Default::default()}).unwrap();assert_eq!(page.totals,all.totals);got.extend(page.groups.iter().flat_map(|g|g.hits.iter().map(|h|h.assertion.id.clone())));cursor=page.next_cursor;}assert!(cursor.is_none());assert_eq!(got,expected);assert_eq!(engine.resolve(&RelationTarget::Local(LocalRef::Assertion(expected[0].clone()))).unwrap().status,ReferenceStatus::Resolved);assert_eq!(engine.resolve(&RelationTarget::Unknown).unwrap().status,ReferenceStatus::Unknown);assert_eq!(engine.exact("ABSENT_A03_S03",DictionaryExactOptions::default()).unwrap().totals.occurrences,0);
 let resolved=engine.resolve(&RelationTarget::Catalog(CatalogTarget{source:SourceId::new("lensisku").unwrap(),release:rel,native_entry_id:None,native_assertion_id:None,occurrence:Some(excluded)})).unwrap();assert_eq!(resolved.status,ReferenceStatus::Resolved);assert_eq!(resolved.confirmed.len(),1);assert!(!resolved.confirmed[0].current_eligible);assert!(resolved.confirmed[0].payload_present && resolved.confirmed[0].raw.is_some());
 println!("PASS independent public API synthetics, explicit provenance/ID/conflict counterparts and tiny composed store/query/pages/references");
 let full=vlajmaji_data_la_lojban::release_bytes();assert_eq!(full,vlajmaji::data_la_lojban::release_bytes());assert_eq!(vlajmaji_data_la_lojban::seal_bytes(),vlajmaji::data_la_lojban::seal_bytes());let loaded=vlajmaji_data_la_lojban::load().unwrap();assert_eq!((loaded.metadata().entries.len(),loaded.metadata().assertions.len(),loaded.metadata().contexts.len(),loaded.metadata().forms.len(),loaded.metadata().etymologies.len(),loaded.metadata().extensions.len()),(17056,17056,47557,1548,1428,39974));
 let joined=compose_dictionaries(vec![vlajmaji::data_lensisku_jbotci::load().unwrap(),loaded]).unwrap();let meta=joined.metadata();assert_eq!((joined.registry().as_document().sources.len(),joined.registry().as_document().distributors.len(),joined.captures().len(),meta.entries.len(),meta.assertions.len()),(1,2,3,50582,50582));let entries:std::collections::BTreeMap<_,_>=meta.entries.iter().map(|e|(&e.id,e)).collect();let eligible:std::collections::BTreeSet<_>=meta.assertions.iter().filter(|a|a.eligibility==Eligibility::Lexical).map(|a|match &entries[&a.entry].spelling {Presence::Value(w)=>w.clone(),_=>panic!("eligible spelling missing")}).collect();assert_eq!(eligible.len(),31250);assert_eq!(meta.assertions.iter().filter(|a|a.eligibility==Eligibility::Lexical).count(),50572);
 println!("{}",serde_json::json!({"status":"PASS","embedded_full_la_bytes":full.len(),"embedded_full_la_sha256":sha(full),"actual_combined_assertions":50582,"actual_combined_eligible_spellings":eligible.len(),"source_authorities":1,"distribution_captures":3}));
}
